let activeTab = "faq";
let resourcesSearchQuery = "";
let faqSearchQuery = "";
let directivesSearchQuery = "";

/* ==========================================
   INITIALIZATION
   ========================================== */
document.addEventListener("DOMContentLoaded", () => {
  setupMobileMenu();
  setupTheme();
  setupLanguage();
  setupTabSystem();
  setupSearchEngine();
  renderActiveTab();
});

/* ==========================================
   MOBILE HAMBURGER MENU
   ========================================== */
function setupMobileMenu() {
  const hamburger = document.getElementById("hamburger");
  const navMenu = document.getElementById("navMenu");
  const navLinks = document.querySelectorAll(".nav-link");

  if (hamburger && navMenu) {
    hamburger.addEventListener("click", () => {
      hamburger.classList.toggle("open");
      navMenu.classList.toggle("open");
    });

    navLinks.forEach(link => {
      link.addEventListener("click", () => {
        hamburger.classList.remove("open");
        navMenu.classList.remove("open");
      });
    });
  }
}

/* ==========================================
   THEME TOGGLER (DAY / NIGHT)
   ========================================== */
function setupTheme() {
  document.body.classList.add("light-mode");
}

/* ==========================================
   LANGUAGE SWITCHER SYSTEM
   ========================================== */
function setupLanguage() {
  const langSelect = document.getElementById("langSelect");
  let currentLang = localStorage.getItem("language") || "tr";
  
  if (langSelect) {
    langSelect.value = currentLang;
    langSelect.addEventListener("change", (e) => {
      const selectedLang = e.target.value;
      localStorage.setItem("language", selectedLang);
      updatePageLanguage(selectedLang);
      document.documentElement.lang = selectedLang;
      renderActiveTab(); // Re-render content to translate dynamic segments
    });
  }
  
  updatePageLanguage(currentLang);
}

function updatePageLanguage(lang) {
  const translatableElements = document.querySelectorAll("[data-i18n]");

  translatableElements.forEach(element => {
    const key = element.getAttribute("data-i18n");
    if (translations[key] && translations[key][lang]) {
      element.textContent = translations[key][lang];
    }
  });

  const searchInput = document.getElementById("resourcesSearchInput");
  if (searchInput) {
    searchInput.placeholder = lang === "tr" ? "Kaynaklarda arayın..." : "Search resources...";
  }
}

/* ==========================================
   TAB SYSTEM LOGIC
   ========================================== */
function setupTabSystem() {
  const tabs = document.querySelectorAll(".resources-tab-btn, .binder-tab");
  tabs.forEach(tab => {
    tab.addEventListener("click", () => {
      tabs.forEach(t => {
        t.classList.remove("active");
        if (t.hasAttribute("aria-selected")) {
          t.setAttribute("aria-selected", "false");
        }
      });
      tab.classList.add("active");
      if (tab.hasAttribute("aria-selected")) {
        tab.setAttribute("aria-selected", "true");
      }
      activeTab = tab.getAttribute("data-tab");
      // Reset search inputs on tab change to prevent confusing results
      const searchInput = document.getElementById("resourcesSearchInput");
      if (searchInput) {
        searchInput.value = "";
        resourcesSearchQuery = "";
      }
      faqSearchQuery = "";
      directivesSearchQuery = "";
      renderActiveTab();
    });
  });
}

/* ==========================================
   SEARCH ENGINE LOGIC
   ========================================== */
function setupSearchEngine() {
  const searchInput = document.getElementById("resourcesSearchInput");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      resourcesSearchQuery = e.target.value.toLowerCase().trim();
      renderActiveTab();
    });
  }
}

/* ==========================================
   RENDER CORE CONTENT PANE
   ========================================== */
function renderActiveTab() {
  const contentPane = document.getElementById("resourcesContentPane");
  if (!contentPane) return;

  const lang = localStorage.getItem("language") || "tr";
  
  // Clean container
  contentPane.innerHTML = "";

  // Title translation
  const tabTitleKey = `tab_${activeTab}`;
  const tabTitle = translations[tabTitleKey][lang];

  // Create Header Section
  const headerHtml = `<h2 class="tab-section-title">${tabTitle}</h2>`;
  
  // Get content generators
  let widgetHtml = "";
  switch (activeTab) {
    case "faq":
      widgetHtml = getFaqWidgetHtml(lang);
      break;
    case "directives":
      widgetHtml = getDirectivesWidgetHtml(lang);
      break;
    case "regions":
      widgetHtml = getRegionsWidgetHtml(lang);
      break;
    case "students":
      widgetHtml = getStudentsWidgetHtml(lang);
      break;
    case "hezarfen":
      widgetHtml = getHezarfenWidgetHtml(lang);
      break;
  }

  // File Downloads Grid
  const downloadsHtml = getDownloadsGridHtml(lang);

  // Combine Layout
  contentPane.innerHTML = headerHtml + widgetHtml + downloadsHtml;

  // Bind Listeners for widgets that are now rendered
  bindWidgetListeners(lang);
}

/* ==========================================
   WIDGET HTML GENERATORS
   ========================================== */

// 1. FAQ Widget & Content
function getFaqWidgetHtml(lang) {
  const widgetTitle = translations["widget_title_faq"][lang];
  const searchPlaceholder = lang === "tr" ? "SSS konularında arayın..." : "Search FAQ topics...";
  
  // Filter FAQs based on either the global search or the local widget search
  const query = resourcesSearchQuery !== "" ? resourcesSearchQuery : faqSearchQuery;
  const filteredFaqs = faqData.filter(item => {
    if (query === "") return true;
    const qText = lang === "tr" ? item.qTR.toLowerCase() : item.qEN.toLowerCase();
    const aText = lang === "tr" ? item.aTR.toLowerCase() : item.aEN.toLowerCase();
    return qText.includes(query) || aText.includes(query);
  });

  let faqItemsHtml = "";
  if (filteredFaqs.length === 0) {
    faqItemsHtml = `<div class="downloads-no-results">${translations["no_results"][lang]}</div>`;
  } else {
    filteredFaqs.forEach((faq, index) => {
      const q = lang === "tr" ? faq.qTR : faq.qEN;
      const a = lang === "tr" ? faq.aTR : faq.aEN;
      faqItemsHtml += `
        <div class="faq-item" id="faqItem-${index}">
          <button class="faq-question-btn" onclick="toggleFaq(${index})">
            <span>${q}</span>
            <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
              <path d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"/>
            </svg>
          </button>
          <div class="faq-answer" id="faqAnswer-${index}">
            <div class="faq-answer-inner">${a}</div>
          </div>
        </div>
      `;
    });
  }

  return `
    <div class="widget-container">
      <div class="widget-header">
        <h3 class="widget-title">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 16h-2v-2h2v2zm1.07-7.75l-.9.92C12.45 11.9 12 12.5 12 14h-2v-.5c0-1.1.45-2.1 1.17-2.83l1.24-1.26c.37-.36.59-.86.59-1.41 0-1.1-.9-2-2-2s-2 .9-2 2H7c0-2.76 2.24-5 5-5s5 2.24 5 5c0 1.04-.42 1.99-1.07 2.75z"/></svg>
          <span>${widgetTitle}</span>
        </h3>
        <span class="widget-badge live">${lang === "tr" ? "Yardım" : "Help"}</span>
      </div>
      <div class="widget-faq-search-wrapper">
        <input type="text" class="widget-faq-search-input" id="widgetFaqSearchInput" placeholder="${searchPlaceholder}" value="${faqSearchQuery}">
      </div>
      <div class="faq-accordion">
        ${faqItemsHtml}
      </div>
    </div>
  `;
}

// Global toggle for FAQ accordions
window.toggleFaq = function(index) {
  const item = document.getElementById(`faqItem-${index}`);
  const answer = document.getElementById(`faqAnswer-${index}`);
  if (!item || !answer) return;

  const isOpen = item.classList.contains("open");
  
  // Close all other items first
  document.querySelectorAll(".faq-item").forEach(el => el.classList.remove("open"));
  document.querySelectorAll(".faq-answer").forEach(el => el.style.maxHeight = null);

  if (!isOpen) {
    item.classList.add("open");
    answer.style.maxHeight = answer.scrollHeight + "px";
  }
};

// 2. Directives Widget
function getDirectivesWidgetHtml(lang) {
  const widgetTitle = translations["widget_title_directives"][lang];
  const query = resourcesSearchQuery !== "" ? resourcesSearchQuery : directivesSearchQuery;
  
  const filteredDirectives = directivesData.filter(item => {
    if (query === "") return true;
    const name = lang === "tr" ? item.nameTR.toLowerCase() : item.nameEN.toLowerCase();
    const code = item.code.toLowerCase();
    return name.includes(query) || code.includes(query);
  });

  let directivesHtml = "";
  if (filteredDirectives.length === 0) {
    directivesHtml = `<div class="downloads-no-results">${translations["no_results"][lang]}</div>`;
  } else {
    filteredDirectives.forEach(item => {
      const name = lang === "tr" ? item.nameTR : item.nameEN;
      const statusText = lang === "tr" ? (item.status === "active" ? "Yürürlükte" : "Revize Edildi") : (item.status === "active" ? "Active" : "Revised");
      directivesHtml += `
        <div class="shgm-portal-item">
          <div class="shgm-info">
            <span class="shgm-code">${item.code}</span>
            <span class="shgm-name">${name}</span>
          </div>
          <span class="shgm-status ${item.status}">${statusText}</span>
        </div>
      `;
    });
  }

  const placeholder = lang === "tr" ? "Talimat adı veya kod arayın..." : "Search directives by name/code...";

  return `
    <div class="widget-container">
      <div class="widget-header">
        <h3 class="widget-title">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
          <span>${widgetTitle}</span>
        </h3>
        <span class="widget-badge live">SHGM LIVE</span>
      </div>
      <div class="widget-faq-search-wrapper">
        <input type="text" class="widget-faq-search-input" id="widgetDirectivesSearchInput" placeholder="${placeholder}" value="${directivesSearchQuery}">
      </div>
      <div class="shgm-portal-list">
        ${directivesHtml}
      </div>
    </div>
  `;
}

