// 4. Students Widget (Class Training Roadmap Timeline)
function getStudentsWidgetHtml(lang) {
  // Initialize student progress checklist data
  let checklist = [];
  const saved = localStorage.getItem("student_checklist");
  if (saved) {
    checklist = JSON.parse(saved);
  } else {
    checklist = [
      { id: "ppl", labelTR: "PPL (Hususi Pilot Lisansı) ve Teorik Eğitim", labelEN: "PPL (Private Pilot License) & Theory", checked: true },
      { id: "nr", labelTR: "Gece Yetkisi (Night Rating) Eğitimi", labelEN: "Night Rating (NR) Training", checked: true },
      { id: "pic", labelTR: "PIC Sorumlu Pilot Uçuş Saatleri", labelEN: "PIC Pilot-in-Command Flight Hours", checked: true },
      { id: "ir", labelTR: "Aletli Uçuş Yetkisi (Instrument Rating - IR) Eğitimi", labelEN: "Instrument Rating (IR) Training", checked: true },
      { id: "icao", labelTR: "ICAO Level 4+ İngilizce Yeterlilik Sınavı", labelEN: "ICAO Level 4+ English Proficiency Exam", checked: false },
      { id: "checkride", labelTR: "Kontrol Uçuşu Sınavı (Checkride Exam)", labelEN: "Checkride Exam (Control Flight)", checked: false }
    ];
    localStorage.setItem("student_checklist", JSON.stringify(checklist));
  }

  let checklistHtml = "";
  checklist.forEach(item => {
    const label = lang === "tr" ? item.labelTR : item.labelEN;
    const checkedClass = item.checked ? "checked" : "";
    checklistHtml += `
      <div class="progress-check-item ${checkedClass}" data-id="${item.id}">
        <div class="progress-check-checkbox">
          <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor">
            <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
          </svg>
        </div>
        <span class="progress-check-label">${label}</span>
      </div>
    `;
  });

  const progressWidgetTitle = translations["widget_title_students"][lang];

  const progressWidgetHtml = `
    <div class="widget-container" style="margin-bottom: 30px;">
      <div class="widget-header">
        <h3 class="widget-title">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M12 3L1 9l11 6 9-4.91V17h2V9L12 3zM5.89 12.5L12 15.82l6.11-3.32L12 9.18 5.89 12.5z"/></svg>
          <span>${progressWidgetTitle}</span>
        </h3>
        <span class="widget-badge live">${lang === "tr" ? "Durum" : "Status"}</span>
      </div>
      <div class="student-progress-widget">
        <div class="progress-ring-wrapper">
          <svg class="progress-ring-svg" width="140" height="140">
            <circle class="progress-ring-circle-bg" cx="70" cy="70" r="60"></circle>
            <circle class="progress-ring-circle" cx="70" cy="70" r="60"></circle>
          </svg>
          <div class="progress-percentage" id="progressPercentage">0%</div>
        </div>
        <div class="progress-checklist-wrapper" id="progressChecklistWrapper">
          ${checklistHtml}
        </div>
      </div>
    </div>
  `;

  const widgetTitle = lang === "tr" ? "Aktif & Gelecek Sınıfların Zaman Çizelgesi" : "Active & Upcoming Classes Roadmap";

  const monthsTR = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
  const monthsEN = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const months = lang === "tr" ? monthsTR : monthsEN;

  let headerHtml = "";
  let gridLinesHtml = "";
  months.forEach(m => {
    headerHtml += `<div class="roadmap-month-col">${m}</div>`;
    gridLinesHtml += `<div class="roadmap-grid-line"></div>`;
  });

  let rowsHtml = "";
  Object.keys(classRoadmapData).forEach(key => {
    const rowInfo = classRoadmapData[key];
    const categoryLabel = lang === "tr" ? rowInfo.labelTR : rowInfo.labelEN;
    
    let barsHtml = "";
    rowInfo.classes.forEach(cls => {
      const name = lang === "tr" ? cls.nameTR : cls.nameEN;
      const progressLabel = cls.progress;
      
      // Multi-segment titles & tooltips
      const mainTooltip = lang === "tr"
        ? `${name} (${progressLabel}): Teorik Eğitim + Ort. 1 Gün Pratik/Sınav`
        : `${name} (${progressLabel}): Theoretical Training + Avg. 1 Day Practical/Exam`;
      const theoryTooltip = lang === "tr"
        ? `${name} - Teorik Dersler`
        : `${name} - Theoretical Ground School`;
      const examTooltip = lang === "tr"
        ? `${name} - Pratik Uygulama & Sınav (Ortalama 1 Gün)`
        : `${name} - Practical Flying & Exam (1 Day average)`;

      barsHtml += `
        <div class="roadmap-bar ${cls.status}" style="left: ${cls.left}%; width: ${cls.width}%; top: ${cls.top}px;" title="${mainTooltip}">
          <div class="roadmap-bar-theory" title="${theoryTooltip}">
            <span class="roadmap-bar-title">${name}</span>
            <span class="roadmap-bar-progress">${progressLabel}</span>
          </div>
          <div class="roadmap-bar-exam" title="${examTooltip}">
            <span class="exam-icon">
              <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor">
                <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-9 14l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/>
              </svg>
            </span>
          </div>
        </div>
      `;
    });

    rowsHtml += `
      <div class="roadmap-row ${key}">
        <div class="roadmap-row-category">${categoryLabel}</div>
        <div class="roadmap-row-track">
          ${barsHtml}
        </div>
      </div>
    `;
  });

  return progressWidgetHtml + `
    <div class="widget-container">
      <div class="widget-header">
        <h3 class="widget-title">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M19 3h-1V1h-2v2H8V1H6v2H5c-1.11 0-1.99.9-1.99 2L3 19c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 16H5V8h14v11zM7 10h5v5H7z"/></svg>
          <span>${widgetTitle}</span>
        </h3>
        <span class="widget-badge live">${lang === "tr" ? "Yol Haritası" : "Roadmap"}</span>
      </div>
      
      <!-- Visual Legend for the theory & practical/exam split -->
      <div class="roadmap-legend">
        <div class="roadmap-legend-item">
          <span class="roadmap-legend-color pilotaj"></span>
          <span>${lang === 'tr' ? 'Pilotaj Sınıfı (Teori)' : 'Pilotage Class (Theory)'}</span>
        </div>
        <div class="roadmap-legend-item">
          <span class="roadmap-legend-color iha"></span>
          <span>${lang === 'tr' ? 'İHA Sınıfı (Teori)' : 'UAV Class (Theory)'}</span>
        </div>
        <div class="roadmap-legend-item">
          <span class="roadmap-legend-color ortak"></span>
          <span>${lang === 'tr' ? 'Özel/Ortak Ders (Teori)' : 'Special/Common Class (Theory)'}</span>
        </div>
        <div class="roadmap-legend-item">
          <span class="roadmap-legend-color exam"></span>
          <span>${lang === 'tr' ? 'Pratik & Sınav Günü (Ort. 1 Gün)' : 'Practical & Exam Day (Avg. 1 Day)'}</span>
        </div>
      </div>
      
      <div class="roadmap-widget">
        <div class="roadmap-scale-container">
          
          <!-- Timeline Header -->
          <div class="roadmap-header">
            ${headerHtml}
          </div>
          
          <!-- Dashed Grid Line Overlay -->
          <div class="roadmap-grid-overlay">
            ${gridLinesHtml}
          </div>
          
          <!-- Swimlane Rows -->
          <div class="roadmap-row-list">
            ${rowsHtml}
          </div>
        </div>
      </div>
    </div>
  `;
}

