/* ==========================================
   DOWNLOAD CARDS HTML GENERATOR
   ========================================== */
function getDownloadsGridHtml(lang) {
  const sectionTitle = translations["downloads_section_title"][lang];

  // Filter downloads based on search query and current category
  const filteredDownloads = downloadsData.filter(file => {
    // Category match
    if (file.category !== activeTab) return false;
    
    // Search query match
    if (resourcesSearchQuery !== "") {
      const title = lang === "tr" ? file.titleTR.toLowerCase() : file.titleEN.toLowerCase();
      if (!title.includes(resourcesSearchQuery)) {
        return false;
      }
    }
    return true;
  });

  let cardsHtml = "";
  if (filteredDownloads.length === 0) {
    cardsHtml = `<div class="downloads-no-results">${translations["no_results"][lang]}</div>`;
  } else {
    filteredDownloads.forEach(file => {
      const title = lang === "tr" ? file.titleTR : file.titleEN;
      
      // Determine file icon based on file type
      let fileIcon = "";
      if (file.type === "pdf") {
        fileIcon = `<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M20 2H8c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-8.5 7.5c0 .83-.67 1.5-1.5 1.5H9v2H7.5V8H10c.83 0 1.5.67 1.5 1.5v.5zm5 2c0 .83-.67 1.5-1.5 1.5h-2.5V8H15c.83 0 1.5.67 1.5 1.5v2.5zm4-3.5h-3v1.5h2.5V11H18v2h-1.5V8h4v1.5zM9 9.5h1v1H9v-1zm4.5 1.5h1v1.5h-1V11zM2 6v14c0 1.1.9 2 2 2h14v-2H4V6H2z"/></svg>`;
      } else if (file.type === "zip") {
        fileIcon = `<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M20 6h-8l-2-2H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2zm-6 6h-2v2h2v-2zm0-4h-2v2h2V8zm-2 8h2v-2h-2v2zm6 2h-6v-2h2v-2h-2v-2h2v-2h-2V8h6v10z"/></svg>`;
      } else {
        fileIcon = `<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>`;
      }

      cardsHtml += `
        <div class="download-card">
          <div class="file-icon-wrapper">
            ${fileIcon}
          </div>
          <div class="file-info">
            <h4 class="file-title" title="${title}">${title}</h4>
            <div class="file-meta">
              <span class="file-size-badge">${file.size}</span>
              <span style="text-transform: uppercase;">${file.type}</span>
            </div>
          </div>
          <a href="#" class="file-download-btn" title="${lang === "tr" ? "İndir" : "Download"}" onclick="simulateDownload(event, '${title}')">
            <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
              <path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96zM17 13l-5 5-5-5h3V9h4v4h3z"/>
            </svg>
          </a>
        </div>
      `;
    });
  }

  return `
    <h3 class="tab-section-title" style="margin-top: 40px; margin-bottom: 20px;">${sectionTitle}</h3>
    <div class="downloads-grid">
      ${cardsHtml}
    </div>
  `;
}

// Simulate file downloads
window.simulateDownload = function(e, fileName) {
  e.preventDefault();
  alert(`${fileName} downloading...`);
};

/* ==========================================
   WIDGET EVENT BINDINGS
   ========================================== */
function bindWidgetListeners(lang) {
  // Bind FAQ Local Search Box Listener
  const faqWidgetSearch = document.getElementById("widgetFaqSearchInput");
  if (faqWidgetSearch) {
    faqWidgetSearch.addEventListener("input", (e) => {
      faqSearchQuery = e.target.value.toLowerCase().trim();
      
      // Re-render the FAQ list dynamically inside the widget without re-rendering the whole page to save state
      const query = faqSearchQuery;
      const filteredFaqs = faqData.filter(item => {
        if (query === "") return true;
        const qText = lang === "tr" ? item.qTR.toLowerCase() : item.qEN.toLowerCase();
        const aText = lang === "tr" ? item.aTR.toLowerCase() : item.aEN.toLowerCase();
        return qText.includes(query) || aText.includes(query);
      });

      const accordionContainer = document.querySelector(".faq-accordion");
      if (accordionContainer) {
        let faqItemsHtml = "";
        if (filteredFaqs.length === 0) {
          faqItemsHtml = `<div class="downloads-no-results">${translations["no_results"][lang]}</div>`;
        } else {
          filteredFaqs.forEach((faq, index) => {
            const q = lang === "tr" ? faq.qTR : faq.qEN;
            const a = lang === "tr" ? faq.aTR : faq.aEN;
            faqItemsHtml += `
              <div class="faq-item" id="faqItem-${index}">
                <button class="faq-question-btn" onclick="toggleFaq(${index})">
                  <span>${q}</span>
                  <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                    <path d="M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z"/>
                  </svg>
                </button>
                <div class="faq-answer" id="faqAnswer-${index}">
                  <div class="faq-answer-inner">${a}</div>
                </div>
              </div>
            `;
          });
        }
        accordionContainer.innerHTML = faqItemsHtml;
      }
    });
  }

  // Bind Directives Local Search Box Listener
  const directivesWidgetSearch = document.getElementById("widgetDirectivesSearchInput");
  if (directivesWidgetSearch) {
    directivesWidgetSearch.addEventListener("input", (e) => {
      directivesSearchQuery = e.target.value.toLowerCase().trim();

      const query = directivesSearchQuery;
      const filteredDirectives = directivesData.filter(item => {
        if (query === "") return true;
        const name = lang === "tr" ? item.nameTR.toLowerCase() : item.nameEN.toLowerCase();
        const code = item.code.toLowerCase();
        return name.includes(query) || code.includes(query);
      });

      const listContainer = document.querySelector(".shgm-portal-list");
      if (listContainer) {
        let directivesHtml = "";
        if (filteredDirectives.length === 0) {
          directivesHtml = `<div class="downloads-no-results">${translations["no_results"][lang]}</div>`;
        } else {
          filteredDirectives.forEach(item => {
            const name = lang === "tr" ? item.nameTR : item.nameEN;
            const statusText = lang === "tr" ? (item.status === "active" ? "Yürürlükte" : "Revize Edildi") : (item.status === "active" ? "Active" : "Revised");
            directivesHtml += `
              <div class="shgm-portal-item">
                <div class="shgm-info">
                  <span class="shgm-code">${item.code}</span>
                  <span class="shgm-name">${name}</span>
                </div>
                <span class="shgm-status ${item.status}">${statusText}</span>
              </div>
            `;
          });
        }
        listContainer.innerHTML = directivesHtml;
      }
    });
  }

function updateProgressRing() {
  const checklistContainer = document.getElementById("progressChecklistWrapper");
  if (!checklistContainer) return;

  const items = checklistContainer.querySelectorAll(".progress-check-item");
  const total = items.length;
  let checked = 0;
  items.forEach(item => {
    if (item.classList.contains("checked")) {
      checked++;
    }
  });

  const percentage = total > 0 ? Math.round((checked / total) * 100) : 0;

  const percentageEl = document.getElementById("progressPercentage");
  if (percentageEl) {
    percentageEl.textContent = `${percentage}%`;
  }

  const circle = document.querySelector(".progress-ring-circle");
  if (circle) {
    const circumference = 377;
    const offset = circumference - (percentage / 100) * circumference;
    circle.style.strokeDashoffset = offset;
  }
}

window.toggleChecklistItem = function(id) {
  const itemEl = document.querySelector(`.progress-check-item[data-id="${id}"]`);
  if (!itemEl) return;

  const isChecked = itemEl.classList.contains("checked");
  if (isChecked) {
    itemEl.classList.remove("checked");
  } else {
    itemEl.classList.add("checked");
  }

  // Save to localStorage
  const saved = localStorage.getItem("student_checklist");
  if (saved) {
    const list = JSON.parse(saved);
    const item = list.find(x => x.id === id);
    if (item) {
      item.checked = !isChecked;
      localStorage.setItem("student_checklist", JSON.stringify(list));
    }
  }

  updateProgressRing();
};

  // Bind Student Progress Checklist Click Listeners
  const checklistContainer = document.getElementById("progressChecklistWrapper");
  if (checklistContainer) {
    const items = checklistContainer.querySelectorAll(".progress-check-item");
    items.forEach(item => {
      item.addEventListener("click", () => {
        const id = item.getAttribute("data-id");
        toggleChecklistItem(id);
      });
    });
    updateProgressRing();
  }
}

// Synchronize dynamic resources created/updated via Admin Panel or GitHub API live
(async function syncAdminResources() {
  try {
    let items = [];
    // Fetch local content JSON files
    const localResourceFiles = ['sample-resource.json'];
    await Promise.all(localResourceFiles.map(async fileName => {
      try {
        const paths = [`../content/resources/${fileName}`, `./content/resources/${fileName}`, `content/resources/${fileName}`];
        for (let p of paths) {
          const res = await fetch(p);
          if (res.ok) {
            const data = await res.json();
            if (data && data.id) {
              const idx = items.findIndex(existing => existing.id == data.id);
              if (idx >= 0) {
                items[idx] = data;
              } else {
                items.push(data);
              }
              break;
            }
          }
        }
      } catch (e) {}
    }));

    // Fetch live published resource JSON files directly from GitHub repo (Daphne008/Sapmaz-Academy)
    try {
      const repoOwner = localStorage.getItem('sapmaz_git_owner') || 'Daphne008';
      const repoName = localStorage.getItem('sapmaz_git_repo') || 'Sapmaz-Academy';
      const repoBranch = localStorage.getItem('sapmaz_git_branch') || 'main';

      const apiUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/contents/content/resources?ref=${repoBranch}`;
      const res = await fetch(apiUrl);

      if (res.ok) {
        const files = await res.json();
        const jsonFiles = Array.isArray(files) ? files.filter(f => f.name.endsWith('.json')) : [];

        const fetchedItems = await Promise.all(jsonFiles.map(async f => {
          try {
            const rawRes = await fetch(f.download_url);
            if (rawRes.ok) return await rawRes.json();
          } catch (e) {}
          return null;
        }));

        const validFetched = fetchedItems.filter(item => item && (item.status === 'Published' || !item.status));

        validFetched.forEach(newItem => {
          const idx = items.findIndex(existing => existing.id === newItem.id);
          if (idx >= 0) {
            items[idx] = newItem;
          } else {
            items.push(newItem);
          }
        });
      }
    } catch (err) {
      console.log('Notice: GitHub API fetch for resources offline/rate-limited:', err);
    }

    const publishedResources = items.filter(r => r.status === 'Published');
    if (publishedResources.length > 0 && typeof downloadsData !== 'undefined') {
      publishedResources.forEach(res => {
        const existingIdx = downloadsData.findIndex(d => d.id === res.id);
        const newItem = {
          id: res.id,
          category: res.category || 'directives',
          size: res.fileSize || '2.5 MB',
          type: (res.format && res.format.toLowerCase().includes('zip')) ? 'zip' : 'pdf',
          titleTR: res.titleTR,
          titleEN: res.titleEN || res.titleTR
        };
        if (existingIdx >= 0) {
          downloadsData[existingIdx] = newItem;
        } else {
          downloadsData.unshift(newItem);
        }
      });

      if (typeof renderActiveTab === 'function') {
        renderActiveTab();
      }
    }
  } catch (e) {
    console.log('Admin resources sync notice:', e);
  }
})();